// ABOUTME: Property tests for the largest-remainder allocator, generated by a seeded fast-check run
// ABOUTME: so a failure reproduces: the parts sum to the total exactly, no part crosses zero with the
// ABOUTME: total, the result is deterministic, scaling the weights changes nothing, and a part is
// ABOUTME: never more than one minor unit from its exact share.

import * as fc from 'fast-check';
import { describe, expect, it } from 'vitest';

import { MoneyError, allocate, allocateEqually, add, fromMinor, sum, zero, type CurrencyCode, type Money } from '..';

const OPTIONS = { seed: 20261022, numRuns: 200 } as const;

const CURRENCIES = ['KES', 'UGX', 'KWD', 'JPY', 'USD'] as const;

/** A total that a float would still hold, and a weight list with at least one part that can take a share. */
const total = fc.integer({ min: -100_000_000, max: 100_000_000 });
const weights = fc
  .array(fc.integer({ min: 0, max: 1000 }), { minLength: 1, maxLength: 6 })
  .filter((list) => list.some((weight) => weight > 0));

function refusalOf(work: () => unknown): MoneyError | null {
  try {
    work();
    return null;
  } catch (error) {
    if (error instanceof MoneyError) return error;
    throw error;
  }
}

/** The total of the parts, as a bigint, so the sum invariant is checked exactly. */
function minorTotal(parts: readonly Money[]): bigint {
  return parts.reduce((running, part) => running + BigInt(part.amount_minor), 0n);
}

describe('the parts sum to the total exactly', () => {
  it('for every total, weight list and currency', () => {
    fc.assert(
      fc.property(fc.constantFrom(...CURRENCIES), total, weights, (code, amountMinor, list) => {
        const parts = allocate(fromMinor(amountMinor, code), list);
        expect(parts).toHaveLength(list.length);
        expect(minorTotal(parts)).toBe(BigInt(amountMinor));
        for (const part of parts) {
          expect(part.currency).toBe(code);
          expect(Number.isSafeInteger(part.amount_minor)).toBe(true);
        }
      }),
      OPTIONS
    );
  });

  it('and add() agrees with the parts, which is how a caller reconciles them', () => {
    fc.assert(
      fc.property(fc.constantFrom(...CURRENCIES), total, weights, (code, amountMinor, list) => {
        const parts = allocate(fromMinor(amountMinor, code), list);
        expect(parts.reduce(add, zero(code))).toEqual(fromMinor(amountMinor, code));
        expect(sum(parts)).toEqual(fromMinor(amountMinor, code));
      }),
      OPTIONS
    );
  });

  it('splits a large total no float could hold exactly', () => {
    const parts = allocate(fromMinor(9007199254740991, 'KES'), [1, 1, 1]);
    expect(minorTotal(parts)).toBe(9007199254740991n);
    expect(parts.map((part) => part.amount_minor)).toEqual([3002399751580331, 3002399751580330, 3002399751580330]);
  });
});

describe('a part never crosses zero with the total', () => {
  it('keeps every part non-negative for a non-negative total, and non-positive for a negative one', () => {
    fc.assert(
      fc.property(fc.constantFrom(...CURRENCIES), total, weights, (code, amountMinor, list) => {
        const parts = allocate(fromMinor(amountMinor, code), list);
        for (const part of parts) {
          if (amountMinor >= 0) expect(part.amount_minor).toBeGreaterThanOrEqual(0);
          else expect(part.amount_minor).toBeLessThanOrEqual(0);
        }
      }),
      OPTIONS
    );
  });

  it('gives every part zero when the total is zero', () => {
    fc.assert(
      fc.property(fc.constantFrom(...CURRENCIES), weights, (code, list) => {
        const parts = allocate(zero(code), list);
        expect(parts.every((part) => part.amount_minor === 0)).toBe(true);
      }),
      OPTIONS
    );
  });
});

describe('the result is deterministic and the weights scale freely', () => {
  it('gives the same parts for the same call', () => {
    fc.assert(
      fc.property(fc.constantFrom(...CURRENCIES), total, weights, (code, amountMinor, list) => {
        const value = fromMinor(amountMinor, code);
        expect(allocate(value, list)).toEqual(allocate(value, list));
      }),
      OPTIONS
    );
  });

  it('is unchanged when every weight is multiplied by the same positive factor', () => {
    fc.assert(
      fc.property(fc.constantFrom(...CURRENCIES), total, weights, fc.integer({ min: 1, max: 12 }), (code, amountMinor, list, factor) => {
        const value = fromMinor(amountMinor, code);
        expect(allocate(value, list.map((weight) => weight * factor))).toEqual(allocate(value, list));
      }),
      OPTIONS
    );
  });

  it('reads a decimal weight exactly, so a 33.33 share loses nothing', () => {
    const totalValue = fromMinor(10000, 'KES');
    const parts = allocate(totalValue, [33.33, 33.33, 33.34]);
    expect(minorTotal(parts)).toBe(10000n);
    expect(parts.map((part) => part.amount_minor)).toEqual([3333, 3333, 3334]);
  });
});

describe('a part is never more than one minor unit from its exact share', () => {
  it('holds for every part of every allocation', () => {
    fc.assert(
      fc.property(fc.constantFrom(...CURRENCIES), total, weights, (code, amountMinor, list) => {
        const parts = allocate(fromMinor(amountMinor, code), list);
        const magnitude = amountMinor < 0 ? -BigInt(amountMinor) : BigInt(amountMinor);
        const weightSum = list.reduce((running, weight) => running + BigInt(weight), 0n);
        for (let index = 0; index < parts.length; index += 1) {
          const exact = magnitude * BigInt(list[index]);
          const assigned = (parts[index].amount_minor < 0 ? -BigInt(parts[index].amount_minor) : BigInt(parts[index].amount_minor)) * weightSum;
          // The part is the floor of its exact share, or one unit more, so the two differ by less
          // than one weight-sum: -weightSum < assigned - exact <= weightSum.
          const difference = assigned - exact;
          expect(difference).toBeGreaterThan(-weightSum);
          expect(difference).toBeLessThanOrEqual(weightSum);
        }
      }),
      OPTIONS
    );
  });
});

describe('an equal split keeps the odd minor units early', () => {
  it('sums to the total and never differs by more than one unit', () => {
    fc.assert(
      fc.property(fc.constantFrom(...CURRENCIES), total, fc.integer({ min: 1, max: 12 }), (code, amountMinor, parts) => {
        const shares = allocateEqually(fromMinor(amountMinor, code), parts);
        expect(shares).toHaveLength(parts);
        expect(minorTotal(shares)).toBe(BigInt(amountMinor));
        const smallest = Math.min(...shares.map((share) => share.amount_minor));
        const largest = Math.max(...shares.map((share) => share.amount_minor));
        expect(largest - smallest).toBeLessThanOrEqual(1);
      }),
      OPTIONS
    );
  });

  it('gives the odd unit to the earliest part', () => {
    expect(allocateEqually(fromMinor(100, 'UGX'), 3).map((part) => part.amount_minor)).toEqual([34, 33, 33]);
    expect(allocateEqually(fromMinor(-100, 'UGX'), 3).map((part) => part.amount_minor)).toEqual([-34, -33, -33]);
    expect(allocateEqually(fromMinor(0, 'KES'), 0)).toEqual([]);
  });
});

describe('weights that cannot divide a total are refused', () => {
  it('refuses a negative, non-finite or scientific weight', () => {
    const value = fromMinor(1000, 'KES');
    expect(refusalOf(() => allocate(value, [1, -1]))?.code).toBe('invalid_weight');
    expect(refusalOf(() => allocate(value, [1, Number.NaN]))?.code).toBe('invalid_weight');
    expect(refusalOf(() => allocate(value, [1, Number.POSITIVE_INFINITY]))?.code).toBe('invalid_weight');
    expect(refusalOf(() => allocate(value, [1e-7, 1]))?.code).toBe('invalid_weight');
  });

  it('refuses weights that are all zero, or no weights at all, for a non-zero total', () => {
    expect(refusalOf(() => allocate(fromMinor(1000, 'KES'), [0, 0]))?.code).toBe('invalid_weight');
    expect(refusalOf(() => allocate(fromMinor(1000, 'KES'), []))?.code).toBe('invalid_weight');
    // A zero total has nothing to divide, so the same inputs are accepted and give zero parts.
    expect(allocate(zero('KES'), [0, 0]).map((part) => part.amount_minor)).toEqual([0, 0]);
    expect(allocate(zero('KES'), [])).toEqual([]);
  });

  it('refuses a part count that is not a whole number of zero or more', () => {
    expect(refusalOf(() => allocateEqually(fromMinor(100, 'KES'), -1))?.code).toBe('invalid_weight');
    expect(refusalOf(() => allocateEqually(fromMinor(100, 'KES'), 1.5))?.code).toBe('invalid_weight');
  });

  it('refuses an unknown currency', () => {
    expect(refusalOf(() => allocate({ amount_minor: 100, currency: 'XYZ' as unknown as CurrencyCode }, [1]))?.code).toBe('unknown_currency');
  });
});
